  authAppTokensRefreshPostResponseError;

export const getAuthAppTokensRefreshPostUrl = () => {
  return `/_allauth/app/v1/tokens/refresh`;
};

/**
 * Used to retrieve a new access token. Depending on `settings.HEADLESS_JWT_ROTATE_REFRESH_TOKEN`,
 * a new refresh token is returned as well.
 * @summary Refresh the access token

 */
export const authAppTokensRefreshPost = (
  authRefreshTokenBody?: AuthRefreshTokenBody,
  options?: Parameters<typeof apiRequest>[1],
) => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiRequest<authAppTokensRefreshPostResponse>(
    getAuthAppTokensRefreshPostUrl(),
    {
      operation: {
        operationId: "auth_app_tokens_refresh_post",
        responses: {
          "400": { content: { "application/json": "json" } },
          "410": { content: { "application/json": "json" } },
        },
      },
      ...options,
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...getHeaders(options?.headers),
      },
      body: JSON.stringify(authRefreshTokenBody),
    },
  );
};

