export const getViewItemsUrl = (
  gisToken: string,
  collectionId: string,
  params?: ViewItemsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/v2/gis-ogc/view/${encodeURIComponent(String(gisToken))}/collections/${encodeURIComponent(String(collectionId))}/items?${stringifiedParams}`
    : `/api/v2/gis-ogc/view/${encodeURIComponent(String(gisToken))}/collections/${encodeURIComponent(String(collectionId))}/items`;
};

